#!/usr/bin/env python3
"""Generate the hosted translation nightly guide from the workflow and suite."""

import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
WORKFLOW = ".github/workflows/hosted-translation-nightly.yaml"
SUITE = "tests/integration/sdk/anthropic/test_anthropic_messages_to_openai_live.py"
CONFIG = "tests/integration/fixtures/anthropic/messages-to-openai-live.yaml"
GUIDE = ROOT / "docs/developing/hosted-translation-nightly.md"


def field(pattern, source):
    match = re.search(pattern, source, re.MULTILINE)
    if match is None:
        raise ValueError(f"Missing documentation input: {pattern}")
    return match[1]


def render():
    workflow = (ROOT / WORKFLOW).read_text()
    suite = (ROOT / SUITE).read_text()
    cron = field(r'^\s+- cron: "([^"]+)"$', workflow)
    runner = field(r"^\s+runs-on: (\S+)$", workflow)
    secret = field(r"secrets\.([A-Z_]+)", workflow)
    artifact = field(r"^\s+name: (hosted-\S+-results)$", workflow)
    sdk = field(r'"anthropic==([^"]+)"', suite)
    model = field(r'^MODEL = "([^"]+)"$', suite)

    return f"""# Hosted translation nightly

<!-- Generated by .github/scripts/hosted_translation_docs.py. Do not edit directly. -->

[Hosted Translation Nightly](../../{WORKFLOW}) runs on
`{runner}` at cron `{cron}` (UTC) and supports manual dispatch.
It builds Praxis from the workflow checkout and uses the
`{secret}` Actions secret to call official OpenAI. A missing
secret fails the credential check before the build. Fork schedules skip
the job. Manual runs require the secret in the repository running the job.

The [SDK suite](../../{SUITE}) sends Anthropic Messages requests
through the local [Praxis configuration](../../{CONFIG})
which translates them to OpenAI Chat Completions over TLS. It uses Anthropic Python `{sdk}` and model
`{model}`. It checks completions and token usage, streaming,
tool result continuation, and the upstream error for an unknown model.

To reproduce locally, build with `cargo build --locked -p praxis-ai-proxy`,
start `target/debug/praxis-ai -c {CONFIG}` from the
repository root, with `{secret}` set in the gateway environment.

```bash
PRAXIS_LIVE_MESSAGES_BASE_URL=http://127.0.0.1:8080 \\
  uv run --script \\
  {SUITE}
```

The run summary records the tested commit and configuration. The
`{artifact}` artifact contains JUnit results and gateway logs. Release CI
qualification records this lane when it finds a run for the exact release
commit. A release with no matching run shows `not_run`. Update the pinned
model snapshot in the SDK suite when OpenAI retires it.

Praxis injects the OpenAI key upstream and the SDK uses a dummy local key.
Gateway authorization, tenant isolation, and retries are outside this suite.
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not GUIDE.is_file() or GUIDE.read_text() != expected:
            parser.exit(1, f"Regenerate {GUIDE.relative_to(ROOT)} with python3 {Path(__file__).relative_to(ROOT)}\n")
    else:
        GUIDE.write_text(expected)


if __name__ == "__main__":
    main()
